def T3(a, b, ck, c):
    return {'t': 'cards', 'cols': 3, 'items': [{'k': 'ЗАДАЧА', 'p': a}, {'k': 'РЕШЕНИЕ', 'p': b}, {'k': ck, 'p': c}]}

def ph(prefix, caps, alts=None):
    n = len(caps)
    return {'t': 'shots', 'n': n, 'phone': True,
            'items': [{'img': f'{prefix}-{i+1}', 'alt': caps[i], 'cap': caps[i]} for i in range(n)]}

